#rf-root,.hf-root{--x3:#3f4853;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;}.cam{position:absolute;inset:0;animation:st-cam 5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}.tx-out{transform:translateY(101%);animation:tx-out 0.5s cubic-bezier(.76,0,.24,1) 4.5s both}@keyframes tx-out{to{transform:translateY(0)}}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}@property --n93{syntax:'<integer>';inherits:false;initial-value:2970}
.n93{counter-reset:n93 var(--n93);animation:n93-c 1.3s cubic-bezier(.16,1,.3,1) 0.5s both}
.n93::after{content:counter(n93,decimal)}
@keyframes n93-c{from{--n93:2970}to{--n93:1350}}.pcard{position:absolute;left:110px;right:110px;top:340px;padding:70px 64px;border-radius:56px;background:color-mix(in srgb,var(--rf-surface) 88%,transparent);border:2px solid color-mix(in srgb,var(--rf-text) 10%,transparent);animation:k-rise 1s cubic-bezier(.16,1,.3,1) 0.1s both}
.pb{display:inline-block;font:500 28px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-accent);margin-bottom:30px}
.pp{font-size:56px;font-weight:600;color:var(--rf-muted)}
.pv{font-size:230px;font-weight:600;letter-spacing:-.06em;line-height:1;margin:10px 0 40px;font-variant-numeric:tabular-nums}.pv sup{font-size:.35em;vertical-align:top;position:relative;top:.4em}.pv small{font-size:.22em;letter-spacing:0;color:var(--rf-muted);font-weight:600}
ul{list-style:none;margin:0;padding:40px 0 0;border-top:2px solid color-mix(in srgb,var(--rf-text) 10%,transparent)}
li{display:flex;align-items:center;gap:22px;font-size:42px;font-weight:400;margin-bottom:28px}li .ic{color:var(--rf-muted);flex:none}
.pbtn{margin-top:30px;text-align:center;font-size:44px;font-weight:600;padding:34px;border-radius:28px;background:var(--rf-text);color:var(--rf-bg)}

