.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.ls-hd{position:absolute;left:90px;right:90px;top:230px}
.ls-pl{display:flex;align-items:center;gap:14px;font:500 34px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}
.ls-t{margin-top:26px;font-size:92px;font-weight:var(--rf-heading-weight);letter-spacing:-.04em;line-height:.98}
